function attachReusableRule(path: string, rule: ReusableSchemaRule): void {
  if (!schemaDraft) return;
  const attachment = {
    id: rule.id,
    name: rule.name,
    version: rule.version ?? 1,
    ...(rule.operator ? { operator:rule.operator } : {}),
    ...(rule.propertyPath ? { propertyPath:rule.propertyPath } : {}),
    ...(rule.parameters ? { parameters:rule.parameters } : {}),
    ...(rule.allowedValues ? { allowedValues:structuredClone(rule.allowedValues) } : {}),
    ...(rule.comparison ? { comparison:rule.comparison } : {}),
    ...(rule.limit !== undefined ? { limit:rule.limit } : {}),
    ...(rule.applicableType ? { applicableType:rule.applicableType } : {}),
    ...(rule.severity ? { severity:rule.severity } : {}),
    ...(rule.message ? { message:rule.message } : {}),
    ...(rule.conditionGroup ? { conditionGroup:structuredClone(rule.conditionGroup) } : {}),
    enabled: true,
  };
  schemaDraft = attachRuleToSchemaProperty(schemaDraft, path, attachment);
  persistSchemaEditorDraft(`Attach ${rule.name} to ${path}`);
  renderSchemaDraft();
  focusSchemaPropertyRow(path);
  if(!compactCanonicalEditor)finishSchemaPropertyInteractionReturn();
}

function updateAttachedRule(path: string, id: string, update: (rule: NonNullable<SchemaDefinition["attachedRules"]>[number]) => NonNullable<SchemaDefinition["attachedRules"]>[number] | undefined): void {
  if (!schemaDraft) return;
  const attachedRules = (schemaDraft.attachedRules ?? []).flatMap((rule) => {
    if (rule.id !== id || canonicalRulePropertyPath(rule.propertyPath ?? "") !== canonicalRulePropertyPath(path)) return [rule];
    const next = update(rule);
    return next ? [next] : [];
  });
  schemaDraft = { ...schemaDraft, attachedRules };
  persistSchemaEditorDraft(`Update attached rule on ${path}`);
  renderSchemaDraft();
  focusSchemaPropertyRow(path);
}

function schemaRuleTypeForAttachment(rule: NonNullable<SchemaDefinition["attachedRules"]>[number]): SchemaRuleType {
  const operator = rule.operator?.replaceAll("_", "-").toLowerCase();
  if (operator === "exact-value") return "Exact value";
  if (operator === "allowed-values") return "Allowed values";
  if (operator === "regular-expression" || operator === "regex") return "Regular expression";
  if (operator === "text-length") return "Text length";
  if (operator === "digits-only") return "Digits only";
  if (operator === "numeric-range") return "Numeric range";
  if (operator === "item-count") return "Item count";
  if (operator === "allow-undeclared-properties") return "Allow undeclared properties";
  return "Required";
}

